// 文件管理器工具类
import fetchWithAuth from '@/utils/fetchWithAuth';
import { ElMessage } from 'element-plus';
import i18n from '@/locales';

class FileManager {
    constructor() {
        this.FILE_LIST_PATH = 'data/fileList.json';
        this.fileListCaches = new Map();
        this.storageWarningShown = false;
    }

    normalizeDir(dir = '') {
        return (dir || '').replace(/\\/g, '/').replace(/^\/+/, '').replace(/\/+$/, '');
    }

    getStorageKey(dir = '') {
        const cleanDir = this.normalizeDir(dir);
        return cleanDir ? `${this.FILE_LIST_PATH}_${encodeURIComponent(cleanDir)}` : this.FILE_LIST_PATH;
    }

    // 从本地存储读取指定目录的文件列表
    getLocalFileList(dir = '') {
        const fileList = this.getMutableFileList(dir);
        return {
            ...fileList,
            files: [...(fileList.files || [])],
            directories: [...(fileList.directories || [])],
        };
    }

    getMutableFileList(dir = '') {
        const storageKey = this.getStorageKey(dir);
        if (this.fileListCaches.has(storageKey)) {
            return this.fileListCaches.get(storageKey);
        }

        try {
            const fileList = localStorage.getItem(storageKey);
            const parsed = fileList ? JSON.parse(fileList) : this.createEmptyFileList();
            this.fileListCaches.set(storageKey, parsed);
            return parsed;
        } catch (error) {
            console.error('Error reading local file list:', error);
            const empty = this.createEmptyFileList();
            this.fileListCaches.set(storageKey, empty);
            return empty;
        }
    }

    // 更新内存缓存，并尽量持久化到 localStorage
    updateFileListCache(fileList, dir = '') {
        const storageKey = this.getStorageKey(dir);
        const validList = fileList || this.createEmptyFileList();
        this.fileListCaches.set(storageKey, validList);
        const persisted = this.persistFileListCache(storageKey, validList);

        return {
            cacheUpdated: true,
            persisted,
        };
    }

    persistFileListCache(storageKey, data) {
        try {
            localStorage.setItem(storageKey, JSON.stringify(data));
            return true;
        } catch (error) {
            this.handleStoragePersistError(error, storageKey);
            return false;
        }
    }

    createEmptyFileList() {
        return { files: [], directories: [] };
    }

    handleStoragePersistError(error, storageKey) {
        console.warn('File list is kept in memory because localStorage persistence failed:', error);

        try {
            if (storageKey) {
                localStorage.removeItem(storageKey);
            }
        } catch (removeError) {
            console.warn('Failed to remove stale file list cache:', removeError);
        }

        if (!this.storageWarningShown) {
            this.storageWarningShown = true;
            ElMessage.warning(i18n.global.t('dashboard.fileListMemoryCacheWarning'));
        }
    }

    // 添加新文件到列表
    addFile(newFile) {
        try {
            const fileList = this.getMutableFileList();
            fileList.files.push(newFile);
            return this.updateFileListCache(fileList).cacheUpdated;
        } catch (error) {
            console.error('Error adding file:', error);
            return false;
        }
    }

    // 添加新文件夹
    addFolder(folderName) {
        try {
            const fileList = this.getMutableFileList();
            if (!fileList.directories.includes(folderName)) {
                fileList.directories.push(folderName);
                return this.updateFileListCache(fileList).cacheUpdated;
            }
            return false; // 文件夹已存在
        } catch (error) {
            console.error('Error adding folder:', error);
            return false;
        }
    }

    // 移动文件或文件夹
    moveFile(oldPath, newPath, isFolder = false, currentPath = '') {
        try {
            let fileList = this.getMutableFileList();
            
            if (isFolder) {
                // 更新目录列表
                const oldFolderIndex = fileList.directories.indexOf(oldPath);
                if (oldFolderIndex !== -1) {
                    fileList.directories.splice(oldFolderIndex, 1);
                }

            } else {
                // 移动单个文件
                const fileIndex = fileList.files.findIndex(file => file.name === oldPath);
                if (fileIndex !== -1) {
                    // 从旧位置移除
                    fileList.files.splice(fileIndex, 1);
                }

            }

            // 如果新路径包含当前目录的直接子目录，则添加直接子目录
            if (newPath.startsWith(currentPath)) {
                const pathArray = newPath.substring(currentPath.length).split('/');
                if (pathArray.length > 1) {
                    const newFolder = currentPath + pathArray[0];
                    if (!fileList.directories.includes(newFolder)) {
                        fileList.directories.push(newFolder);
                    }
                }
            }

            return this.updateFileListCache(fileList).cacheUpdated;
        } catch (error) {
            console.error('Error moving file:', error);
            return false;
        }
    }

    // 更新本地列表中单个文件的元数据
    updateFileMetadata(fileName, newMetadata, currentDir = '') {
        try {
            const cleanDir = currentDir ? currentDir.replace(/^\/+/, '').replace(/\/+$/, '') : '';
            let fileList = this.getMutableFileList(cleanDir);
            const target = fileList.files.find(file => file.name === fileName);
            if (target) {
                target.metadata = { ...target.metadata, ...newMetadata };
                return this.updateFileListCache(fileList, cleanDir).cacheUpdated;
            }
            return false;
        } catch (error) {
            console.error('Error updating file metadata:', error);
            return false;
        }
    }

    // 从列表中删除文件
    removeFile(fileName) {
        try {
            let fileList = this.getMutableFileList();
            fileList.files = fileList.files.filter(file => file.name !== fileName);
            return this.updateFileListCache(fileList).cacheUpdated;
        } catch (error) {
            console.error('Error removing file:', error);
            return false;
        }
    }

    // 从列表中删除文件夹（同时删除该文件夹下的所有文件）
    removeFolder(folderName, currentDir = '') {
        try {
            const cleanFolder = (folderName || '').replace(/\\/g, '/').replace(/^\/+/, '').replace(/\/+$/, '');
            let fileList = this.getMutableFileList(currentDir);
            fileList.files = fileList.files.filter(file => {
                const name = (file.name || '').replace(/^\/+/, '');
                return !name.startsWith(cleanFolder + '/');
            });
            fileList.directories = fileList.directories.filter(dir => {
                const cleanDir = (dir || '').replace(/\\/g, '/').replace(/^\/+/, '').replace(/\/+$/, '');
                return cleanDir !== cleanFolder && !cleanDir.startsWith(cleanFolder + '/');
            });

            // 清理该目录自身的持久化缓存
            try {
                localStorage.removeItem(this.getStorageKey(cleanFolder));
                this.fileListCaches.delete(this.getStorageKey(cleanFolder));
            } catch (e) {
                // ignore
            }

            return this.updateFileListCache(fileList, currentDir).cacheUpdated;
        } catch (error) {
            console.error('Error removing folder:', error);
            return false;
        }
    }

    // 获取指定目录下的文件和子目录
    getFilesInFolder(folderName) {
        try {
            const cleanFolder = (folderName || '').replace(/\\/g, '/').replace(/^\/+/, '').replace(/\/+$/, '');
            const fileList = this.getMutableFileList(cleanFolder);
            const files = fileList.files.filter(file => {
                const name = (file.name || '').replace(/^\/+/, '');
                return name.startsWith(cleanFolder + '/');
            });
            const subdirectories = fileList.directories.filter(dir => {
                const cleanDir = (dir || '').replace(/\\/g, '/').replace(/^\/+/, '');
                return cleanDir.startsWith(cleanFolder + '/');
            });
            return { files, directories: subdirectories };
        } catch (error) {
            console.error('Error getting files in folder:', error);
            return { files: [], directories: [] };
        }
    }

    // 构建筛选参数URL
    buildFilterParams(filters) {
        let params = '';
        // 访问状态筛选（综合判断）
        if (filters.accessStatus && filters.accessStatus.length > 0) {
            params += `&accessStatus=${encodeURIComponent(filters.accessStatus.join(','))}`;
        }
        // 黑白名单筛选（直接使用 ListType 字段）
        if (filters.listType && filters.listType.length > 0) {
            params += `&listType=${encodeURIComponent(filters.listType.join(','))}`;
        }
        if (filters.label && filters.label.length > 0) {
            params += `&label=${encodeURIComponent(filters.label.join(','))}`;
        }
        if (filters.fileType && filters.fileType.length > 0) {
            params += `&fileType=${encodeURIComponent(filters.fileType.join(','))}`;
        }
        if (filters.channel && filters.channel.length > 0) {
            params += `&channel=${encodeURIComponent(filters.channel.join(','))}`;
        }
        if (filters.channelName && filters.channelName.length > 0) {
            params += `&channelName=${encodeURIComponent(filters.channelName.join(','))}`;
        }
        return params;
    }

    // 更新文件列表
    async refreshFileList(dir = '', search = '', includeTags = '', excludeTags = '', filters = {}) {
        search = search.trim();
        const cleanDir = this.normalizeDir(dir);
        const normalizedDir = cleanDir ? cleanDir + '/' : '';
        try {
            let url = `/api/manage/list?count=-1&dir=${encodeURIComponent(normalizedDir)}&search=${encodeURIComponent(search)}`;
            if (includeTags) {
                url += `&includeTags=${encodeURIComponent(includeTags)}`;
            }
            if (excludeTags) {
                url += `&excludeTags=${encodeURIComponent(excludeTags)}`;
            }
            // 添加筛选参数（支持多选）
            url += this.buildFilterParams(filters);
            
            const response = await fetchWithAuth(url, {
                method: 'GET',
            });
            if (!response.ok) {
                console.error(`refreshFileList request failed with status: ${response.status}`);
                return false;
            }
            const newFileList = await response.json();
            if (!newFileList || (!Array.isArray(newFileList.files) && !Array.isArray(newFileList.directories))) {
                console.error('refreshFileList received invalid payload:', newFileList);
                return false;
            }
            if (!newFileList.isIndexedResponse) {
                ElMessage.warning(i18n.global.t('dashboard.indexingWarning'));
            }
            // 保存指定目录的完整数据缓存
            return this.updateFileListCache(newFileList, cleanDir).cacheUpdated;
        } catch (error) {
            console.error('Error refreshing file list:', error);
            return false;
        }
    }

    // 读取更多数据
    async loadMoreFiles(dir = '', search = '', includeTags = '', excludeTags = '', count = 60, filters = {}) {
        search = search.trim();
        const cleanDir = this.normalizeDir(dir);
        const normalizedDir = cleanDir ? cleanDir + '/' : '';
        try {
            const fileList = this.getMutableFileList(cleanDir);
            const start = fileList.files.length;

            let url = `/api/manage/list?dir=${encodeURIComponent(normalizedDir)}&start=${start}&count=${count}&search=${encodeURIComponent(search)}`;
            if (includeTags) {
                url += `&includeTags=${encodeURIComponent(includeTags)}`;
            }
            if (excludeTags) {
                url += `&excludeTags=${encodeURIComponent(excludeTags)}`;
            }
            // 添加筛选参数（支持多选）
            url += this.buildFilterParams(filters);

            const response = await fetchWithAuth(url, {
                method: 'GET',
            });
           
            const moreFiles = await response.json();
            fileList.files.push(...(moreFiles.files || []));
            return this.updateFileListCache(fileList, cleanDir).cacheUpdated;
        } catch (error) {
            console.error('Error loading more files:', error);
            return { files: [], directories: [] };
        }
    }
}

export const fileManager = new FileManager();
