/**
 * 判断文件是否为可编辑的纯文本/代码文件
 */

const EDITABLE_EXTENSIONS = new Set([
    'txt', 'text', 'md', 'markdown',
    'json', 'jsonc', 'json5',
    'js', 'mjs', 'cjs', 'ts', 'jsx', 'tsx', 'vue',
    'html', 'htm', 'xhtml',
    'css', 'scss', 'sass', 'less',
    'xml', 'svg',
    'yaml', 'yml', 'toml', 'ini', 'conf', 'config', 'env', 'properties',
    'sh', 'bash', 'zsh', 'bat', 'cmd', 'ps1',
    'py', 'sql', 'log', 'csv', 'tsv',
    'gitignore', 'dockerfile', 'editorconfig',
    'java', 'c', 'cpp', 'h', 'hpp', 'cs', 'go', 'rs', 'php', 'rb', 'lua'
]);

/**
 * 检查文件是否为文本文件
 * @param {Object} file - 文件对象（包含 name 或 metadata）
 * @returns {boolean}
 */
export function isEditableTextFile(file) {
    if (!file) return false;
    if (file.isFolder) return false;

    const fileName = file.metadata?.FileName || file.name || '';
    const cleanName = fileName.split('/').pop() || fileName;
    const ext = cleanName.includes('.') ? cleanName.split('.').pop().toLowerCase() : cleanName.toLowerCase();

    if (EDITABLE_EXTENSIONS.has(ext)) {
        return true;
    }

    const fileType = (file.metadata?.FileType || '').toLowerCase();
    if (
        fileType.startsWith('text/') ||
        fileType.includes('json') ||
        fileType.includes('javascript') ||
        fileType.includes('xml') ||
        fileType.includes('yaml') ||
        fileType.includes('csv')
    ) {
        return true;
    }

    return false;
}

/**
 * 根据文件名推测代码语言类型
 * @param {string} fileName
 * @returns {string}
 */
export function getFileLanguage(fileName = '') {
    const ext = fileName.split('.').pop().toLowerCase();
    const map = {
        js: 'JavaScript',
        mjs: 'JavaScript',
        cjs: 'JavaScript',
        ts: 'TypeScript',
        tsx: 'TypeScript (React)',
        jsx: 'JavaScript (React)',
        vue: 'Vue',
        json: 'JSON',
        html: 'HTML',
        htm: 'HTML',
        css: 'CSS',
        scss: 'SCSS',
        less: 'LESS',
        md: 'Markdown',
        markdown: 'Markdown',
        xml: 'XML',
        svg: 'SVG',
        yaml: 'YAML',
        yml: 'YAML',
        toml: 'TOML',
        ini: 'INI',
        conf: 'Config',
        env: 'Env',
        sh: 'Shell',
        bash: 'Bash',
        py: 'Python',
        sql: 'SQL',
        log: 'Log',
        csv: 'CSV',
        txt: 'Plain Text'
    };
    return map[ext] || 'Text';
}
