import { ElMessage, ElMessageBox } from 'element-plus';
import fetchWithAuth from '@/utils/fetchWithAuth';
import { getFileLanguage } from '@/utils/editableFileHelper';
export default {
  name: 'FileEditorDialog',
  props: {
    modelValue: {
      type: Boolean,
      default: false
    },
    file: {
      type: Object,
      default: null
    }
  },
  emits: ['update:modelValue', 'saved'],
  data() {
    return {
      content: '',
      originalContent: '',
      loading: false,
      saving: false,
      isFullScreen: false
    };
  },
  computed: {
    visible: {
      get() {
        return this.modelValue;
      },
      set(val) {
        this.$emit('update:modelValue', val);
      }
    },
    dialogWidth() {
      if (this.isFullScreen) return '100vw';
      return window.innerWidth < 768 ? '95%' : '85%';
    },
    displayName() {
      return this.file?.metadata?.FileName || this.file?.name || '';
    },
    languageName() {
      return getFileLanguage(this.displayName);
    },
    hasUnsavedChanges() {
      return this.content !== this.originalContent;
    },
    lineCount() {
      if (!this.content) return 1;
      return this.content.split('\n').length;
    },
    charCount() {
      return this.content.length;
    },
    currentSizeFormatted() {
      const bytes = new TextEncoder().encode(this.content).length;
      if (bytes < 1024) return bytes + ' B';
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
      return (bytes / 1024 / 1024).toFixed(2) + ' MB';
    }
  },
  watch: {
    visible(newVal) {
      if (newVal && this.file) {
        this.loadFileContent();
      } else {
        this.resetState();
      }
    }
  },
  methods: {
    resetState() {
      this.content = '';
      this.originalContent = '';
      this.loading = false;
      this.saving = false;
      this.isFullScreen = false;
    },
    toggleFullScreen() {
      this.isFullScreen = !this.isFullScreen;
    },
    handleScroll(e) {
      if (this.$refs.lineNumbersRef && e.target) {
        this.$refs.lineNumbersRef.scrollTop = e.target.scrollTop;
      }
    },
    handleKeyDown(e) {
      // Tab 键处理：插入2个空格
      if (e.key === 'Tab') {
        e.preventDefault();
        const textarea = e.target;
        const start = textarea.selectionStart;
        const end = textarea.selectionEnd;
        const insertText = '  ';
        this.content = this.content.substring(0, start) + insertText + this.content.substring(end);
        this.$nextTick(() => {
          textarea.selectionStart = textarea.selectionEnd = start + insertText.length;
        });
        return;
      }

      // Ctrl+S / Cmd+S 快捷保存
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
        e.preventDefault();
        if (this.hasUnsavedChanges && !this.saving) {
          this.saveContent();
        }
      }
    },
    async copyAllContent() {
      try {
        await navigator.clipboard.writeText(this.content);
        ElMessage.success(this.$t('fileEditor.copySuccess'));
      } catch (err) {
        ElMessage.error(this.$t('fileEditor.copyFailed'));
      }
    },
    tryClose() {
      this.handleBeforeClose(() => {
        this.visible = false;
      });
    },
    handleBeforeClose(done) {
      if (this.hasUnsavedChanges) {
        ElMessageBox.confirm(this.$t('fileEditor.unsavedWarningText'), this.$t('fileEditor.unsavedWarningTitle'), {
          confirmButtonText: this.$t('fileEditor.discardChanges'),
          cancelButtonText: this.$t('fileEditor.keepEditing'),
          type: 'warning'
        }).then(() => {
          done();
        }).catch(() => {});
      } else {
        done();
      }
    },
    async loadFileContent() {
      if (!this.file || !this.file.name) return;
      this.loading = true;
      try {
        const fileId = this.file.name;
        const res = await fetchWithAuth(`/api/manage/content/${encodeURIComponent(fileId)}`);
        const data = await res.json();
        if (res.ok && data.success) {
          this.content = data.content || '';
          this.originalContent = this.content;
        } else {
          throw new Error(data.message || this.$t('fileEditor.readFailed'));
        }
      } catch (err) {
        console.error('Failed to load file content:', err);
        ElMessage.error(err.message || this.$t('fileEditor.readFailed'));
        this.visible = false;
      } finally {
        this.loading = false;
      }
    },
    async saveContent() {
      if (!this.file || !this.file.name) return;
      this.saving = true;
      try {
        const fileId = this.file.name;
        const res = await fetchWithAuth(`/api/manage/content/${encodeURIComponent(fileId)}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            content: this.content
          })
        });
        const data = await res.json();
        if (res.ok && data.success) {
          this.originalContent = this.content;
          ElMessage.success(this.$t('fileEditor.saveSuccess'));
          this.$emit('saved', data.metadata);
        } else {
          throw new Error(data.message || this.$t('fileEditor.saveFailed'));
        }
      } catch (err) {
        console.error('Failed to save file content:', err);
        ElMessage.error(err.message || this.$t('fileEditor.saveFailed'));
      } finally {
        this.saving = false;
      }
    }
  }
};